    /**
     * Tests getting all ThirdPartys.
     *
     * @return    Collection
     */
    public List<ThirdParty> testGetAll() throws Throwable {
    LOGGER.info( "ThirdPartyTest:testGetAll() - Retrieving Collection of ThirdPartys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ThirdParty : " );
    List<ThirdParty> collection  = null;

    try {
        // call the static get method on the ThirdPartyService
        collection = service.getAllThirdParty();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ThirdParty currEntity  = null;
            Iterator<ThirdParty> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getThirdPartyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

